document.querySelectorAll('.spb').forEach(root => {
  const trigger = root.querySelector('.spb__a'), menu = root.querySelector('.spb__menu');
  const items = () => [...menu.querySelectorAll('[role=menuitem]')];
  const close = refocus => { menu.hidden = true; trigger.setAttribute('aria-expanded', 'false'); if (refocus) trigger.focus(); };
  const open = first => {
    menu.hidden = false; trigger.setAttribute('aria-expanded', 'true');
    const list = items(); (first === 'last' ? list[list.length - 1] : list[0]).focus();
  };
  trigger.addEventListener('click', () => menu.hidden ? open() : close(true));
  trigger.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown') { e.preventDefault(); open(); } else if (e.key === 'ArrowUp') { e.preventDefault(); open('last'); }
  });
  menu.addEventListener('keydown', e => {
    const list = items(), i = list.indexOf(document.activeElement);
    const to = { ArrowDown: (i + 1) % list.length, ArrowUp: (i - 1 + list.length) % list.length, Home: 0, End: list.length - 1 }[e.key];
    if (to !== undefined) { e.preventDefault(); list[to].focus(); }
    else if (e.key === 'Escape') { e.preventDefault(); close(true); }
    else if (e.key === 'Tab') close(false);
  });
  menu.addEventListener('click', e => { if (e.target.closest('[role=menuitem]')) close(true); });
  document.addEventListener('click', e => { if (!root.contains(e.target)) close(false); });
});
